def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    current = chain_dict['a']
    result = []
    while current:
        next_token = current.pop()
        result.append(next_token)
        if next_token not in chain_dict:
            break
        current = chain_dict[next_token]

    return ','.join(result)

# Example usage:
# print(chain_follow(['bbb', 'ccc']))  # Output: 'a,b,c,d'
